import re,json
P=open('/home/user/fortress/explorations/coordinator/PLAN.md',encoding='utf-8').read().split('\n')
rq=json.load(open('rq.json'))
RQ=open('/home/user/fortress/explorations/coordinator/review-queue.md',encoding='utf-8').read().split('\n')
# headings
head=None; plan=[]
for i,l in enumerate(P,1):
    if l.startswith('#'): head=l.lstrip('#').strip(); continue
    if l.strip(): plan.append((i,head,l))
# home references in queue: PLAN, "Heading", first words
homes=[]  # (qnum, heading, words)
for k,v in rq.items():
    for it in v:
        h=it['home'] if it['sec']!='(a)' else it['text']
        for m in re.finditer(r'PLAN, "([^"]+)", ([^;]+?)(?:;|$|\(10-02)',h):
            homes.append((int(k),it['sec'],m.group(1),m.group(2).strip()))
# also lines anywhere in RQ text with PLAN, "heading"
def norm(s): return re.sub(r'[^a-z0-9]+',' ',s.lower()).strip()
out={}
for (i,h,l) in plan:
    if i<15 or i>702: continue
    body=l.lstrip(' -').strip()
    nb=norm(body)
    cites=sorted(set(int(x) for x in re.findall(r'[Rr]eview-queue items? (\d+)',l)))
    # also lists "items 4 and 82"
    for m in re.finditer(r'[Rr]eview-queue items ([\d, and]+)',l):
        cites+= [int(x) for x in re.findall(r'\d+',m.group(1))]
    cites=sorted(set(cites))
    hm=[]
    for (q,sec,hh,w) in homes:
        if norm(hh)==norm(h) or (h and norm(h).startswith(norm(hh))):
            nw=norm(w)
            if nw and len(nw)>8 and nb.startswith(nw[:max(12,len(nw)-6)]): hm.append((q,sec))
    out[i]=dict(head=h,chars=len(l)+1,cites=cites,homes=sorted(set(hm)),first=body[:90])
json.dump(out,open('map.json','w'))
for i in sorted(out):
    o=out[i]
    c=[(q,rq[str(q)][0]['sec'] if str(q) in rq else '?') for q in o['cites']]
    print(i,o['chars'],'C',c,'H',o['homes'],'|',o['first'][:70])
EOF
